SELECT 
FROM TBL_GUARANTEE_APPLICATION
WHERE (DELETE_FLAG = 0 OR DELETE_FLAG IS NULL)

    AND GUARANTEE_TYPE = #{guaranteeType}


    AND APPLICATION_STATUS = #{applicationStatus}


    AND APPLICATION_NO LIKE CONCAT('%', #{applicationNo}, '%')


    AND APPLICANT_ID = #{applicantId}


    AND GUARANTOR_ID = #{guarantorId}

ORDER BY APPLY_DATE DESC

mapper.update:
UPDATE TBL_GUARANTEE_APPLICATION
SET APPLICATION_STATUS = #{status}, UPDATED_TIME = SYSDATE
WHERE APPLICATION_ID = #{applicationId}

UPDATE TBL_GUARANTEE_APPLICATION
APPLICATION_NO = #{applicationNo}, GUARANTEE_TYPE = #{guaranteeType}, APPLY_AMOUNT = #{guaranteeAmount}, APPROVED_AMOUNT = #{approvedAmount}, CURRENCY_CODE = #{currencyCode}, GUARANTOR_ID = #{guarantorId}, GUARANTOR_NAME = #{guarantorName}, APPLICANT_ID = #{applicantId}, APPLICANT_NAME = #{applicantName}, APPLICATION_STATUS = #{applicationStatus}, APPLY_DATE = #{applyDate}, EXPECTED_START_DATE = #{expectedStartDate}, EXPECTED_END_DATE = #{expectedEndDate}, UPDATED_TIME = SYSDATE
WHERE APPLICATION_ID = #{applicationId}

UPDATE TBL_GUARANTEE_APPLICATION
SET DELETE_FLAG = 1, UPDATED_TIME = SYSDATE
WHERE APPLICATION_ID = #{applicationId}
